interface LeftMetric { default String units() { return "m"; } }
interface RightMetric { default String units() { return "metres"; } }
interface MetricChoice extends LeftMetric, RightMetric {
    default String units() { return LeftMetric.super.units(); }
}
class MeasuredPoint implements MetricChoice {}
public class InterfaceDiamondDemo {
    public static void main(String[] args) { System.out.println(new MeasuredPoint().units()); }
}
